create index if not exists idx_records_user_status on aroma_records(user_id, status, made_at); create index if not exists idx_ingredients_record on aroma_ingredients(aroma_record_id, sort_order); create index if not exists idx_images_user on brainwave_images(user_id, created_at); create index if not exists idx_hearing_record on hearing_sheets(aroma_record_id); create index if not exists idx_favorites_user on favorites(user_id, aroma_record_id); create table if not exists audit_logs ( id text primary key, actor_user_id text not null, actor_role text not null, action text not null, target_table text not null, target_id text, subject_user_id text, reason text, created_at text not null default (datetime('now')), check (action in ('view', 'create', 'update', 'delete', 'export', 'print')) ); create index if not exists idx_audit_subject on audit_logs(subject_user_id, created_at); create index if not exists idx_audit_actor on audit_logs(actor_user_id, created_at); create index if not exists idx_audit_created on audit_logs(created_at); create table if not exists consents ( id text primary key, user_id text not null references profiles(user_id) on delete cascade, consent_type text not null, granted integer not null default 1, document_version text not null, obtained_by text, obtained_at text not null, revoked_at text, note text not null default '', check (consent_type in ('measurement', 'data_use', 'image_storage', 'third_party')), check (granted in (0, 1)) ); create index if not exists idx_consents_user on consents(user_id, consent_type, obtained_at); create table if not exists store_staff ( id text primary key, store_id text not null references stores(id) on delete cascade, user_id text not null references profiles(user_id) on delete cascade, created_at text not null default (datetime('now')), unique (store_id, user_id) ); create table if not exists visits ( id text primary key, store_id text not null references stores(id) on delete cascade, user_id text not null references profiles(user_id) on delete cascade, staff_user_id text references profiles(user_id) on delete set null, session_number text unique, visited_at text not null default (datetime('now')), note text not null default '', created_at text not null default (datetime('now')), check (session_number is null or (length(session_number) = 11 and session_number glob '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]')) ); create index if not exists idx_visits_store_user on visits(store_id, user_id); create index if not exists idx_visits_store_date on visits(store_id, visited_at); create index if not exists idx_visits_user_date on visits(user_id, visited_at); create index if not exists idx_store_staff_user on store_staff(user_id); create index if not exists idx_visits_store_day on visits(store_id, substr(visited_at, 1, 10));
